import sys
T = int(sys.stdin.readline())
for _ in range(T):
	N = int(sys.stdin.readline())
	B = list(map(int, sys.stdin.readline().split()))
	k = 0
	for i in range(len(B) - 1):
		if bin(B[i] & ~B[i + 1]).count('1') > 0:
			k = -1
			break
		k += bin(B[i] & B[i + 1]).count('1')
	if k == -1:
		print(0)
	else:
		print(2 ** k % 1000000007)
